import { StyleSheet } from 'react-native';

const styles = StyleSheet.create({
    containerPrice: {
        backgroundColor: '#0B0D33',
        alignItems: 'center',
        paddingVertical: 5
    },

    textPrice: {
        color: '#fff',
        fontSize: 20
    },

    valuePrice: {
        color: '#fff',
        fontSize: 18,
        paddingHorizontal: 50,
    },

    description: {
        fontSize: 19,
        color: '#fff',
        marginHorizontal: 15,
        paddingVertical: 15
    },

    button: {
        backgroundColor: '#333',
        paddingHorizontal: 50,
        borderRadius: 10
    },
});
export { styles };
